/* cppi::21df1246f727935eed1eb26327e808f38ebbb81bd875f62b0e7d3acb3ac49d39 */
SELECT COUNT(*) FROM (WITH filtered_index AS (SELECT business_date, id_cppib_index, index_description, rimes_source_code, rimes_source_description, index_value_base, return_daily_base, inception_return_base, feed_version FROM market.cppib_index WHERE id_cppib_index = 'BMIRGLFF00X_CNR_CAD_0_0' AND business_date BETWEEN DATE '2025-04-30' AND DATE '2025-06-02') SELECT f.business_date, f.id_cppib_index, f.index_description, f.return_daily_base, f.inception_return_base FROM filtered_index f JOIN (SELECT business_date, max(feed_version) AS feed_version FROM filtered_index GROUP BY business_date) latest ON f.business_date = latest.business_date AND f.feed_version = latest.feed_version
) dbvrcnt

/* cppi::696bb7d0e62bb1bbdb52791a71627a63db245faab52f32d26abfe5dfab307b06 */
select business_date as date_, security_id, 'SP500_25' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-02' and business_date <= date '2025-06-02' and weight_ndo>0 and id_cppib_index = 'SP500_25_GR_USD_0_0' and security_id is not null

